// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 vb, uint128 vn, uint8 d) public {
        vb = uint128(bound(vb, 1, type(uint128).max));
        vn = uint128(bound(vn, 1, type(uint128).max));
        vm.assume(d >= 4 && d <= 36 && d != 18);
        MockERC20 base = new MockERC20(d);
        try c.initialize(address(base), address(0x1), vb, vn, 0, 0, bytes32(0), false, false) {
            assertTrue(c.price() == (uint256(vb) * 10 ** (36 - d)) / uint256(vn));
        } catch {
            assertTrue(false, "initialize should succeed");
        }
    }
}

contract MockERC20 {
    uint8 public immutable d;
    constructor(uint8 d_) { d = d_; }
    function decimals() external view returns (uint8) { return d; }
}
